/**
 * The tables a new workbench opens with.
 *
 * A city's taxi trips, generated rather than downloaded: the point of
 * the sample is millions of rows on the first frame, and a download of
 * that size would make the first frame a progress bar. Generated by
 * DuckDB itself, from `range()` and `hash()`, so it is the same data on
 * every machine and every reload, and a spec can name the row a query
 * puts first.
 *
 * The shape is the familiar one from the public taxi data — pickup and
 * dropoff times and zones, distance, fare, tip and how it was paid —
 * with the distributions bent towards the real ones: more trips in the
 * evening than at 4am, most of them short, tips mostly on cards.
 */

export const DEFAULT_SAMPLE_ROWS = 5_000_000;
export const SAMPLE_SIZES: readonly number[] = [1_000_000, 5_000_000, 10_000_000];

/** Real neighbourhoods, by borough, so a GROUP BY reads like something. */
const ZONES: readonly (readonly [string, string])[] = [
  ['Manhattan', 'Midtown Center'], ['Manhattan', 'Upper East Side North'], ['Manhattan', 'Upper East Side South'],
  ['Manhattan', 'Upper West Side North'], ['Manhattan', 'Upper West Side South'], ['Manhattan', 'Times Sq/Theatre District'],
  ['Manhattan', 'Murray Hill'], ['Manhattan', 'Lincoln Square East'], ['Manhattan', 'East Village'], ['Manhattan', 'West Village'],
  ['Manhattan', 'Greenwich Village North'], ['Manhattan', 'Clinton East'], ['Manhattan', 'Gramercy'], ['Manhattan', 'Chelsea'],
  ['Manhattan', 'Financial District North'], ['Manhattan', 'TriBeCa/Civic Center'], ['Manhattan', 'Lenox Hill West'],
  ['Manhattan', 'Penn Station/Madison Sq West'], ['Manhattan', 'Union Sq'], ['Manhattan', 'Harlem'],
  ['Brooklyn', 'Williamsburg (North Side)'], ['Brooklyn', 'Park Slope'], ['Brooklyn', 'Downtown Brooklyn/MetroTech'],
  ['Brooklyn', 'Greenpoint'], ['Brooklyn', 'Bushwick South'], ['Brooklyn', 'Fort Greene'], ['Brooklyn', 'Crown Heights North'],
  ['Brooklyn', 'Brooklyn Heights'], ['Queens', 'JFK Airport'], ['Queens', 'LaGuardia Airport'], ['Queens', 'Astoria'],
  ['Queens', 'Long Island City/Hunters Point'], ['Queens', 'Jackson Heights'], ['Queens', 'Flushing'], ['Queens', 'Forest Hills'],
  ['Bronx', 'Mott Haven/Port Morris'], ['Bronx', 'Fordham South'], ['Bronx', 'Riverdale/North Riverdale/Fieldston'],
  ['Staten Island', 'St. George/New Brighton'], ['EWR', 'Newark Airport']
];

export function zoneCount(): number {
  return ZONES.length;
}

function quote(text: string): string {
  return `'${text.replaceAll("'", "''")}'`;
}

/** A uniform number in [0, 1) for row `i`, stream `k`: deterministic, and different per stream. */
function uniform(k: number): string {
  return `((hash(i * 2654435761 + ${k}) % 1000003) / 1000003.0)`;
}

export function sampleStatements(rows: number): string[] {
  const zones = ZONES.map(([borough, zone], index) => `(${index + 1}, ${quote(borough)}, ${quote(zone)})`).join(',\n  ');
  // Trip hour: the mean of two uniforms is a triangle, laid across the
  // whole day from 7am round to 7am with its peak at 7pm, so every hour
  // has trips, the evening has the most, and 4am the fewest.
  const hour = `(floor((${uniform(1)} + ${uniform(2)}) * 0.5 * 24 + 7)::INTEGER % 24)`;
  return [
    `CREATE OR REPLACE TABLE zones AS SELECT * FROM (VALUES\n  ${zones}\n) AS z(zone_id, borough, zone)`,
    `CREATE OR REPLACE TABLE trips AS
WITH base AS (
  SELECT
    i,
    TIMESTAMP '2024-01-01'
      + to_days((${uniform(3)} * 366)::INTEGER)
      + to_hours(${hour})
      + to_seconds((${uniform(4)} * 3600)::INTEGER) AS pickup_at,
    -- Most trips are short: the square of a uniform leans towards zero.
    round(0.3 + pow(${uniform(5)}, 2.2) * 24, 2) AS distance_miles,
    1 + (pow(${uniform(6)}, 1.6) * ${ZONES.length})::INTEGER % ${ZONES.length} AS pickup_zone,
    1 + (pow(${uniform(7)}, 1.4) * ${ZONES.length})::INTEGER % ${ZONES.length} AS dropoff_zone,
    CASE WHEN ${uniform(8)} < 0.72 THEN 1 WHEN ${uniform(8)} < 0.88 THEN 2 WHEN ${uniform(8)} < 0.94 THEN 3
         WHEN ${uniform(8)} < 0.97 THEN 4 ELSE 5 + (${uniform(9)} * 2)::INTEGER END AS passengers,
    CASE WHEN ${uniform(10)} < 0.76 THEN 'card' WHEN ${uniform(10)} < 0.97 THEN 'cash'
         WHEN ${uniform(10)} < 0.99 THEN 'no charge' ELSE 'dispute' END AS payment,
    ${uniform(11)} AS u_tip,
    ${uniform(12)} AS u_speed
  FROM range(${Math.max(1, Math.floor(rows))}) t(i)
)
SELECT
  i + 1 AS trip_id,
  CASE WHEN i % 3 = 0 THEN 'CMT' ELSE 'VTS' END AS vendor,
  pickup_at,
  pickup_at + to_seconds((distance_miles / (6 + u_speed * 14) * 3600)::INTEGER + 90) AS dropoff_at,
  passengers,
  distance_miles,
  pickup_zone,
  dropoff_zone,
  payment,
  round(3.0 + distance_miles * 2.5 + u_speed * 4, 2)::DECIMAL(10, 2) AS fare,
  CASE WHEN payment = 'card' THEN round((3.0 + distance_miles * 2.5) * (0.1 + u_tip * 0.18), 2) ELSE 0 END::DECIMAL(10, 2) AS tip
FROM base`
  ];
}

/** What the editor holds the first time it is opened. */
export const WELCOME = `-- Welcome to Gesso SQL: DuckDB, in your browser, behind an interface that never waits for it.
-- The trips table is generated on start. Put the caret in a query and press Ctrl+Enter (⌘+Enter on a Mac).
-- Ctrl+Shift+Enter runs the whole script, Ctrl+/ comments lines, and Ctrl+Shift+F lays the SQL out.
-- In the grid: Shift+arrows select a range, Ctrl+C copies it (Ctrl+Shift+C with column names), Enter shows a value in full.

-- Busiest pickup zones, with average fare and tip rate.
SELECT z.borough, z.zone, count(*) AS trips,
       round(avg(t.fare), 2) AS avg_fare,
       round(100 * sum(t.tip) / sum(t.fare), 1) AS tip_pct
FROM trips t
JOIN zones z ON z.zone_id = t.pickup_zone
GROUP BY ALL
ORDER BY trips DESC;

-- Every trip, all of them: scroll the grid while the next query runs.
SELECT * FROM trips;

-- Trips by hour of day: open the Chart tab after running this.
SELECT hour(pickup_at) AS hour, count(*) AS trips
FROM trips
GROUP BY 1
ORDER BY 1;

-- A deliberately heavy one: a window function over every row.
SELECT trip_id, pickup_at, fare,
       avg(fare) OVER (PARTITION BY pickup_zone ORDER BY pickup_at
                       ROWS BETWEEN 1000 PRECEDING AND CURRENT ROW) AS rolling_fare
FROM trips
ORDER BY rolling_fare DESC;

SUMMARIZE trips;
`;
